import{J as e,n as t,ot as n,q as r}from"./chunks/framework.1lTNTJZP.js";var i=JSON.parse(`{"title":"Class: ChunkPyramid","description":"","frontmatter":{"head":[["meta",{"property":"og:title","content":"Class: ChunkPyramid"}],["meta",{"property":"og:description","content":""}],["meta",{"property":"og:url","content":"https://jsprismarine.dev/api/@jsprismarine/chunkgen/classes/ChunkPyramid"}],["link",{"rel":"canonical","href":"https://jsprismarine.dev/api/@jsprismarine/chunkgen/classes/ChunkPyramid"}]],"editSource":{"kind":"folder","url":"https://github.com/JSPrismarine/JSPrismarine/tree/master/packages/chunkgen/src"}},"headers":[],"relativePath":"api/@jsprismarine/chunkgen/classes/ChunkPyramid.md","filePath":"api/@jsprismarine/chunkgen/classes/ChunkPyramid.md","lastUpdated":1794433523000}`),a={name:`api/@jsprismarine/chunkgen/classes/ChunkPyramid.md`};function o(t,i,a,o,s,c){return n(),r(`div`,null,[...i[0]||=[e(`<p><a href="./../../../">API reference</a> / <a href="./../">@jsprismarine/chunkgen</a> / ChunkPyramid</p><h1 id="class-chunkpyramid" tabindex="-1">Class: ChunkPyramid <a class="header-anchor" href="#class-chunkpyramid" aria-label="Permalink to “Class: ChunkPyramid”">​</a></h1><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/9e7a309dfc4f623e5fde581afd2983b76bc73a55/packages/chunkgen/src/ChunkPyramid.ts#L47" target="_blank" rel="noreferrer">ChunkPyramid.ts:47</a></p><p>A step per status, built in ladder order so each one can close over the windows below it.</p><p>Java has two of these. This is <code>GENERATION_PYRAMID</code>, the one that applies when a chunk has to be generated. <code>LOADING_PYRAMID</code>, which applies when every chunk in range is already persisted deep enough to read from disk, is not reproduced here.</p><h2 id="constructors" tabindex="-1">Constructors <a class="header-anchor" href="#constructors" aria-label="Permalink to “Constructors”">​</a></h2><h3 id="constructor" tabindex="-1">Constructor <a class="header-anchor" href="#constructor" aria-label="Permalink to “Constructor”">​</a></h3><blockquote><p><strong>new ChunkPyramid</strong>(<code>declarations</code>): <code>ChunkPyramid</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/9e7a309dfc4f623e5fde581afd2983b76bc73a55/packages/chunkgen/src/ChunkPyramid.ts#L51" target="_blank" rel="noreferrer">ChunkPyramid.ts:51</a></p><h4 id="parameters" tabindex="-1">Parameters <a class="header-anchor" href="#parameters" aria-label="Permalink to “Parameters”">​</a></h4><h5 id="declarations" tabindex="-1">declarations <a class="header-anchor" href="#declarations" aria-label="Permalink to “declarations”">​</a></h5><p><code>Readonly</code>&lt;<code>Record</code>&lt;<a href="./../#chunkstatus"><code>ChunkStatus</code></a>, <code>StepDeclaration</code>&gt;&gt;</p><p>One declaration per status, applied in <a href="./../#chunk-statuses">CHUNK_STATUSES</a> order.</p><h4 id="returns" tabindex="-1">Returns <a class="header-anchor" href="#returns" aria-label="Permalink to “Returns”">​</a></h4><p><code>ChunkPyramid</code></p><h2 id="methods" tabindex="-1">Methods <a class="header-anchor" href="#methods" aria-label="Permalink to “Methods”">​</a></h2><h3 id="radiusof" tabindex="-1">radiusOf() <a class="header-anchor" href="#radiusof" aria-label="Permalink to “radiusOf()”">​</a></h3><blockquote><p><strong>radiusOf</strong>(<code>status</code>, <code>target?</code>): <code>number</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/9e7a309dfc4f623e5fde581afd2983b76bc73a55/packages/chunkgen/src/ChunkPyramid.ts#L76" target="_blank" rel="noreferrer">ChunkPyramid.ts:76</a></p><p>How far a status must have spread around a chunk before that chunk can reach <code>target</code>.</p><p>This is the number the parallel design turns on. For a <code>full</code> target it reads 11 for <code>empty</code> and <code>structure_starts</code>, 3 for <code>structure_references</code> and <code>biomes</code>, 2 for <code>terrain</code>, 1 for <code>features</code> and <code>initialize_light</code>, and 0 for <code>light</code> and <code>spawn</code>.</p><h4 id="parameters-1" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-1" aria-label="Permalink to “Parameters”">​</a></h4><h5 id="status" tabindex="-1">status <a class="header-anchor" href="#status" aria-label="Permalink to “status”">​</a></h5><p><code>&quot;empty&quot;</code> | <code>&quot;structure_starts&quot;</code> | <code>&quot;structure_references&quot;</code> | <code>&quot;biomes&quot;</code> | <code>&quot;terrain&quot;</code> | <code>&quot;features&quot;</code> | <code>&quot;initialize_light&quot;</code> | <code>&quot;light&quot;</code> | <code>&quot;spawn&quot;</code> | <code>&quot;full&quot;</code></p><h5 id="target" tabindex="-1">target? <a class="header-anchor" href="#target" aria-label="Permalink to “target?”">​</a></h5><p><code>&quot;empty&quot;</code> | <code>&quot;structure_starts&quot;</code> | <code>&quot;structure_references&quot;</code> | <code>&quot;biomes&quot;</code> | <code>&quot;terrain&quot;</code> | <code>&quot;features&quot;</code> | <code>&quot;initialize_light&quot;</code> | <code>&quot;light&quot;</code> | <code>&quot;spawn&quot;</code> | <code>&quot;full&quot;</code> = <code>&#39;full&#39;</code></p><h4 id="returns-1" tabindex="-1">Returns <a class="header-anchor" href="#returns-1" aria-label="Permalink to “Returns”">​</a></h4><p><code>number</code></p><p>The radius in chunks, or -1 when the target does not depend on that status at all.</p><hr><h3 id="stepto" tabindex="-1">stepTo() <a class="header-anchor" href="#stepto" aria-label="Permalink to “stepTo()”">​</a></h3><blockquote><p><strong>stepTo</strong>(<code>status</code>): <a href="./ChunkStep.html"><code>ChunkStep</code></a></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/9e7a309dfc4f623e5fde581afd2983b76bc73a55/packages/chunkgen/src/ChunkPyramid.ts#L60" target="_blank" rel="noreferrer">ChunkPyramid.ts:60</a></p><p>The step that takes a chunk from the status below up to this one.</p><h4 id="parameters-2" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-2" aria-label="Permalink to “Parameters”">​</a></h4><h5 id="status-1" tabindex="-1">status <a class="header-anchor" href="#status-1" aria-label="Permalink to “status”">​</a></h5><p><code>&quot;empty&quot;</code> | <code>&quot;structure_starts&quot;</code> | <code>&quot;structure_references&quot;</code> | <code>&quot;biomes&quot;</code> | <code>&quot;terrain&quot;</code> | <code>&quot;features&quot;</code> | <code>&quot;initialize_light&quot;</code> | <code>&quot;light&quot;</code> | <code>&quot;spawn&quot;</code> | <code>&quot;full&quot;</code></p><h4 id="returns-2" tabindex="-1">Returns <a class="header-anchor" href="#returns-2" aria-label="Permalink to “Returns”">​</a></h4><p><a href="./ChunkStep.html"><code>ChunkStep</code></a></p>`,39)]])}var s=t(a,[[`render`,o]]);export{i as __pageData,s as default};